workers = snapshot["workers"]

# Reservation workers detail - all same request date?
print("=== RESERVATION WORKER RUN DETAILS ===")
for w in workers:
    if w["task"] == "reservation":
        last = w["recent_runs"][0]
        print(f"  {w['name']}: request={last.get('request')}, decision={last.get('decision')}, reason={last.get('reason')}, state_before={last.get('state_before')}, state_after={last.get('state_after')}, ok={last.get('ok')}, problems={last.get('problems')}")

# How many reservation workers share the same digest?
res_digests = {}
for w in workers:
    if w["task"] == "reservation":
        d = w["version_history"][0]["digest"]
        res_digests.setdefault(d, []).append(w["name"])
print("\n=== RESERVATION DIGEST GROUPS ===")
for d, names in res_digests.items():
    print(f"  {d[:16]}...: {len(names)} workers")

# All reservation workers share same engine, effect, digest
print(f"\nTotal reservation workers: {sum(1 for w in workers if w['task']=='reservation')}")

# Check: do all reservation workers request 2026-05-05?
all_same_request = all(
    w["recent_runs"][0].get("request") == "2026-05-05"
    for w in workers if w["task"] == "reservation"
)
print(f"All reservation workers request 2026-05-05: {all_same_request}")

# Check state_before for all reservation workers
state_befores = set()
for w in workers:
    if w["task"] == "reservation":
        for r in w["recent_runs"]:
            state_befores.add(r.get("state_before"))
print(f"Distinct state_before values across all reservation runs: {state_befores}")

